1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	/**
59	 * A fractional amount is always rounded in the MHPCO's favour, once, at the end
60	 * of the calculation it concludes. Which direction that is depends on who pays:
61	 * the customer pays a premium, so it rounds up; the MHPCO pays a claim, so it
62	 * rounds down. Intermediate amounts stay fractional.
63	 */
64	const roundPremiumInMHPCOsFavour = Math.ceil;
65	const roundPayoutInMHPCOsFavour = Math.floor;
66	
67	const BASE_PREMIUMS: Record<string, number> = {
68	  sword: 100,
69	  amulet: 60,
70	  staff: 80,
71	  potion: 40,
72	  rune: 25,
73	  moonstone: 25,
74	};
75	
76	/** Components are the small parts — runes, moonstones — as opposed to main items. */
77	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
78	
79	/** The block discount is a components-only offer. */
80	const ALIKE_ITEMS_BLOCK = { size: 3, basePremium: 60 };
81	
82	const formsBlock = (type: string, count: number): boolean =>
83	  COMPONENT_TYPES.has(type) && count === ALIKE_ITEMS_BLOCK.size;
84	
85	const basePremiumForItemType = (type: string, count: number): number =>
86	  formsBlock(type, count)
87	    ? ALIKE_ITEMS_BLOCK.basePremium
88	    : count * BASE_PREMIUMS[type];
89	
90	/**
91	 * Tallies a list of type names. Callers project their own shape onto the type
92	 * it names, so a policy's items and a claim's damages — which spell the field
93	 * differently — are counted by the same rule.
94	 */
95	const countByType = (types: readonly string[]): Map<string, number> =>
96	  types.reduce(
97	    (counts, type) => counts.set(type, (counts.get(type) ?? 0) + 1),
98	    new Map<string, number>(),
99	  );
100	
101	const policyBasePremium = (items: Item[]): number =>
102	  [...countByType(items.map((item) => item.type))].reduce(
103	    (total, [type, count]) => total + basePremiumForItemType(type, count),
104	    0,
105	  );
106	
107	const CURSE_SURCHARGE_RATE = 0.5;
108	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
109	const HIGH_ENCHANTMENT_LEVEL = 5;
110	
111	const isHighlyEnchanted = (item: Item): boolean =>
112	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
113	
114	interface RiskFactor {
115	  applies: (item: Item) => boolean;
116	  rate: number;
117	}
118	
119	const RISK_FACTORS: RiskFactor[] = [
120	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
121	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
122	];
123	
124	const itemRiskSurcharge = (item: Item): number =>
125	  RISK_FACTORS.reduce(
126	    (total, { applies, rate }) =>
127	      applies(item) ? total + BASE_PREMIUMS[item.type] * rate : total,
128	    0,
129	  );
130	
131	const totalRiskSurcharges = (items: Item[]): number =>
132	  items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
133	
134	const LOYALTY_DISCOUNT_RATE = -0.2;
135	const LOYALTY_YEARS = 2;
136	
137	const isLoyal = (customer: Customer): boolean =>
138	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
139	
140	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
141	
142	/** A quote in the context of the customer's history with the MHPCO. */
143	interface Contract {
144	  customer: Customer;
145	  /** Zero-based ordinal of this quote among the customer's quotes. */
146	  ordinal: number;
147	}
148	
149	const isFollowUpContract = (contract: Contract): boolean =>
150	  contract.ordinal > 0;
151	
152	/**
153	 * Policy-wide modifiers are charged on the policy base premium, unlike the
154	 * item-specific RISK_FACTORS which are charged on each affected item's own
155	 * base premium. Rates are signed: negative is a discount.
156	 */
157	interface PolicyFactor {
158	  applies: (contract: Contract) => boolean;
159	  rate: number;
160	}
161	
162	const POLICY_FACTORS: PolicyFactor[] = [
163	  {
164	    applies: ({ customer }) => isLoyal(customer),
165	    rate: LOYALTY_DISCOUNT_RATE,
166	  },
167	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
168	  {
169	    applies: isFollowUpContract,
170	    rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
171	  },
172	];
173	
174	const totalPolicyAdjustments = (
175	  policyBase: number,
176	  contract: Contract,
177	): number =>
178	  POLICY_FACTORS.reduce(
179	    (total, { applies, rate }) =>
180	      applies(contract) ? total + policyBase * rate : total,
181	    0,
182	  );
183	
184	/** The MHPCO only insures what is on its price list. */
185	const rejectUnknownItemTypes = (items: Item[]): void => {
186	  for (const item of items) {
187	    if (!(item.type in BASE_PREMIUMS)) {
188	      throw new ClaimOfficeError(
189	        `the MHPCO does not insure items of type ${item.type}`,
190	      );
191	    }
192	  }
193	};
194	
195	const quotePremium = (items: Item[], contract: Contract): number => {
196	  rejectUnknownItemTypes(items);
197	  const policyBase = policyBasePremium(items);
198	  return roundPremiumInMHPCOsFavour(
199	    policyBase +
200	      totalRiskSurcharges(items) +
201	      totalPolicyAdjustments(policyBase, contract) +
202	      PROCESSING_FEE,
203	  );
204	};
205	
206	const INSURANCE_VALUES: Record<string, number> = {
207	  sword: 1000,
208	  amulet: 600,
209	  staff: 800,
210	  potion: 400,
211	  rune: 250,
212	  moonstone: 250,
213	};
214	
215	const DEDUCTIBLE_PER_DAMAGE = 100;
216	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
217	
218	const insuranceSum = (items: Item[]): number =>
219	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
220	
221	const payoutCap = (items: Item[]): number =>
222	  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
223	
224	/**
225	 * Distinct from the premium side's HIGH_ENCHANTMENT_LEVEL of 5: the payout
226	 * rule and the surcharge rule share a shape but not a threshold.
227	 */
228	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
229	const HALF_REIMBURSEMENT_RATE = 0.5;
230	const FULL_REIMBURSEMENT_RATE = 1;
231	
232	/**
233	 * The share of a damage amount the MHPCO reimburses, before the deductible.
234	 * Damage to a heavily enchanted item is reimbursed at half.
235	 */
236	const reimbursementRate = (item: Item): number =>
237	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
238	    ? HALF_REIMBURSEMENT_RATE
239	    : FULL_REIMBURSEMENT_RATE;
240	
241	/** Business the MHPCO refuses to transact. Reported to the customer as-is. */
242	export class ClaimOfficeError extends Error {}
243	
244	/**
245	 * What a policy covers, indexed by item type: how many of that type are
246	 * insured, and — since the reimbursement rate depends on the item's own
247	 * enchantment — one insured item to read that rate from.
248	 *
249	 * Both claim-side questions are asked of this one structure: the overclaim
250	 * guard reads `count`, the payout reads `insuredItem`.
251	 *
252	 * When a policy covers several items of one type with differing enchantments,
253	 * `insuredItem` is the FIRST such item, and every damage of that type is
254	 * reimbursed at its rate. No example in the spec pins which item a damage
255	 * entry attaches to, so this preserves the original behaviour rather than
256	 * inventing a rule; revisit if the spec ever distinguishes them.
257	 */
258	interface Cover {
259	  count: number;
260	  insuredItem: Item;
261	}
262	
263	const coverByType = (policyItems: Item[]): ReadonlyMap<string, Cover> =>
264	  policyItems.reduce((cover, item) => {
265	    const alreadyCovered = cover.get(item.type);
266	    return cover.set(item.type, {
267	      count: (alreadyCovered?.count ?? 0) + 1,
268	      insuredItem: alreadyCovered?.insuredItem ?? item,
269	    });
270	  }, new Map<string, Cover>());
271	
272	/**
273	 * A claim is settled in full or not at all: damaging more items of a type than
274	 * the policy covers rejects the whole claim. An uninsured type — and an item
275	 * type the office does not know at all — is the zero-cover case.
276	 */
277	const rejectOverclaimedTypes = (
278	  damages: Damage[],
279	  cover: ReadonlyMap<string, Cover>,
280	): void => {
281	  for (const [type, claimed] of countByType(
282	    damages.map((damage) => damage.itemType),
283	  )) {
284	    const insured = cover.get(type)?.count ?? 0;
285	    if (claimed > insured) {
286	      throw new ClaimOfficeError(
287	        `claim covers ${claimed} ${type} damages but the policy insures ${insured}`,
288	      );
289	    }
290	  }
291	};
292	
293	/**
294	 * Reads the item a damage entry was filed against. Total because
295	 * `rejectOverclaimedTypes` has already rejected every damage whose type the
296	 * policy does not cover — so by the time a payout is computed, the lookup
297	 * cannot miss.
298	 */
299	const insuredItemFor = (
300	  damage: Damage,
301	  cover: ReadonlyMap<string, Cover>,
302	): Item => {
303	  const covered = cover.get(damage.itemType);
304	  if (covered === undefined) {
305	    throw new ClaimOfficeError(
306	      `the policy does not cover a ${damage.itemType}`,
307	    );
308	  }
309	  return covered.insuredItem;
310	};
311	
312	const damagePayout = (
313	  damage: Damage,
314	  cover: ReadonlyMap<string, Cover>,
315	): number =>
316	  damage.amount * reimbursementRate(insuredItemFor(damage, cover)) -
317	  DEDUCTIBLE_PER_DAMAGE;
318	
319	/** Damage is a loss, never a gain. */
320	const rejectNegativeAmounts = (damages: Damage[]): void => {
321	  for (const damage of damages) {
322	    if (damage.amount < 0) {
323	      throw new ClaimOfficeError(
324	        `damage to a ${damage.itemType} cannot be negative: ${damage.amount}`,
325	      );
326	    }
327	  }
328	};
329	
330	const claimResult = (
331	  step: ClaimStep,
332	  policyItems: Item[],
333	  capAlreadyUsed: number,
334	): ClaimResult => {
335	  rejectNegativeAmounts(step.incident.damages);
336	  const cover = coverByType(policyItems);
337	  rejectOverclaimedTypes(step.incident.damages, cover);
338	  const claimed = roundPayoutInMHPCOsFavour(
339	    step.incident.damages.reduce(
340	      (total, damage) => total + damagePayout(damage, cover),
341	      0,
342	    ),
343	  );
344	  // The cap covers the policy's whole lifetime, so a claim can only draw on
345	  // what earlier claims against the same policy have left.
346	  const capLeft = payoutCap(policyItems) - capAlreadyUsed;
347	  const payout = Math.min(claimed, capLeft);
348	  return { payout, remainingCap: capLeft - payout };
349	};
350	
351	/**
352	 * The items covered by the policy a claim is filed against. A claim's `policy`
353	 * is the index of the quote step that established the policy.
354	 *
355	 * Assumes that step is in fact a quote; no test yet covers a claim pointing at
356	 * a non-quote step, so the assumption is asserted rather than checked.
357	 */
358	const policyItemsFor = (steps: Step[], claim: ClaimStep): Item[] =>
359	  (steps[claim.policy] as QuoteStep).items;
360	
361	/**
362	 * What running the steps so far has established. Steps are settled in order and
363	 * each one reads this, so it carries everything a later step needs to know
364	 * about its predecessors.
365	 */
366	interface Ledger {
367	  /** Results of the steps settled so far, in step order. */
368	  results: StepResult[];
369	  /** Payout drawn against each policy so far, keyed by its quote step's index. */
370	  capUsedByPolicy: ReadonlyMap<number, number>;
371	  /** How many quotes have been settled: the next quote's contract ordinal. */
372	  quotesSoFar: number;
373	}
374	
375	const EMPTY_LEDGER: Ledger = {
376	  results: [],
377	  capUsedByPolicy: new Map(),
378	  quotesSoFar: 0,
379	};
380	
381	const settleQuote = (
382	  step: QuoteStep,
383	  customer: Customer,
384	  ledger: Ledger,
385	): Ledger => ({
386	  ...ledger,
387	  results: [
388	    ...ledger.results,
389	    {
390	      premium: quotePremium(step.items, {
391	        customer,
392	        ordinal: ledger.quotesSoFar,
393	      }),
394	    },
395	  ],
396	  quotesSoFar: ledger.quotesSoFar + 1,
397	});
398	
399	const settleClaim = (
400	  step: ClaimStep,
401	  steps: Step[],
402	  ledger: Ledger,
403	): Ledger => {
404	  const capUsed = ledger.capUsedByPolicy.get(step.policy) ?? 0;
405	  const result = claimResult(step, policyItemsFor(steps, step), capUsed);
406	  return {
407	    ...ledger,
408	    results: [...ledger.results, result],
409	    capUsedByPolicy: new Map(ledger.capUsedByPolicy).set(
410	      step.policy,
411	      capUsed + result.payout,
412	    ),
413	  };
414	};
415	
416	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
417	  const { results } = steps.reduce(
418	    (ledger, step) =>
419	      step.op === "claim"
420	        ? settleClaim(step, steps, ledger)
421	        : settleQuote(step, customer, ledger),
422	    EMPTY_LEDGER,
423	  );
424	  return { results };
425	};
426

1	import { runScenario, type Scenario } from "./claim-office.js";
