3	const readStdin = async (): Promise<string> => {
4	  const chunks: string[] = [];
5	  process.stdin.setEncoding("utf8");
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk);
8	  }
9	  return chunks.join("");
10	};
11	
12	const main = async (): Promise<void> => {
13	  const scenario = JSON.parse(await readStdin()) as Scenario;
14	  process.stdout.write(JSON.stringify(runScenario(scenario)));
15	};
16	
17	try {
18	  await main();
19	} catch (error) {
20	  // The customer is told what went wrong, not how the office is built.
21	  process.stderr.write(`${(error as Error).message}\n`);
22	  process.exit(1);
23	}
