 */
const damagePayout = (
  damage: Damage,
  cover: ReadonlyMap<string, Cover>,
): number => {
  const { insuredItem } = cover.get(damage.itemType)!;
  return damage.amount * reimbursementRate(insuredItem) - DEDUCTIBLE_PER_DAMAGE;
